const request = require('supertest');
const { describe, test, expect } = require('vitest');
const app = require('../app');

describe('GET /api/health', () => {
  test('returns 200 OK with status ok', async () => {
    const res = await request(app).get('/api/health');
    if (res.status !== 200) throw new Error(`Expected status 200 but got ${res.status}`);
    if (res.body.status !== 'ok') throw new Error(`Expected { status: 'ok' }`);
  });
});
